        public static Data PreviewData(){var d=Store.Initial();var a=Account.New("国服主号（示例）","CN");a.Username="晨风 · 战网昵称";a.LoginAccount="cn-demo@example.invalid";a.Password="FAKE_PREVIEW_SECRET";a.LoginMethod="手机号 + 将军令";a.AuthenticatorMemo="将军令在常用手机上；登录时先打开 App。";a.Note="常用游戏账号，邮箱与手机号均可登录。";a.Favorite=true;d.Accounts.Add(a);d.Accounts.Add(Account.New("国服小号（示例）","CN"));var b=Account.New("外服主号（示例）","GLOBAL");b.Username="Wind · BattleTag";b.LoginAccount="global-demo@example.invalid";b.Password="FAKE_PREVIEW_SECRET_2";b.LoginMethod="邮箱 + 验证器";b.AuthenticatorMemo="验证器在备用手机上。";b.Note="美洲区账号；游戏与地区信息可在这里备忘。";b.Favorite=true;d.Accounts.Add(b);return d;}
        Button ActionButton(Panel parent,string text,Action action,bool primary){var b=Ui.Button(text,delegate{if(preview||busy)return;try{RequireVaultAccess();action();}catch(Exception e){status.Text=e is InvalidOperationException?e.Message:"操作未完成，原资料已保留。请保留此提示；不要发送密码或登录网址。";ShowRecovery();}},primary);parent.Children.Add(b);return b;}
        Account Require(){RequireVaultAccess();if(Selected==null)throw new InvalidOperationException("请先选择或添加一个账号。");return Selected;}
        void SetRegion(string value){Stop();HidePassword();region=value;search.Text="";Refresh();}
        void Refresh(string selectedId=null){string id=selectedId??(Selected==null?null:Selected.Id);var items=Accounts.Find(data,region,search.Text,favoriteOnly.IsChecked==true,archivedOnly.IsChecked==true);list.ItemsSource=items;list.SelectedItem=items.FirstOrDefault(a=>a.Id==id)??items.FirstOrDefault();empty.Visibility=items.Count==0?Visibility.Visible:Visibility.Collapsed;empty.Text=archivedOnly.IsChecked==true?"暂无隐藏的账号。":"没有匹配的账号，点击“添加账号”创建备忘。";counts.Text="国服 "+data.Accounts.Count(a=>a.Region=="CN"&&!a.Archived)+" 个 · 外服 "+data.Accounts.Count(a=>a.Region=="GLOBAL"&&!a.Archived)+" 个";cn.Background=region=="CN"?Ui.Brush("#EAF0FF"):Brushes.White;global.Background=region=="GLOBAL"?Ui.Brush("#EAF0FF"):Brushes.White;UpdateDetails();}
        static string Display(string text,string empty){return string.IsNullOrWhiteSpace(text)?empty:text;}
        void UpdateDetails(){var a=Selected;UpdateQuickCopy(a);UpdateWorkspace(a);title.Text=a==null?(region=="CN"?"国服账号":"外服账号"):a.Name;subtitle.Text=a==null?"先添加账号，或切换区服查找已有资料。":(a.Region=="CN"?"国服":"外服")+(a.Archived?" · 已隐藏":" · 账号备忘");user.Text=a==null?"—":Display(a.Username,"未填写");login.Text=a==null?"—":Display(a.LoginAccount,"未填写");method.Text=a==null?"登录方式：未备注":"登录方式："+Display(a.LoginMethod,"未备注");auth.Text=a==null?"未备注":Display(a.AuthenticatorMemo,"未备注");note.Text=a==null?"未填写":Display(a.Note,"未填写");favoriteButton.Content=a!=null&&a.Favorite?"取消收藏":"收藏";archiveButton.Content=a!=null&&a.Archived?"显示账号":"隐藏账号";browserCard.Visibility=region=="CN"&&a!=null&&!a.Archived?Visibility.Visible:Visibility.Collapsed;route.Visibility=browserCard.Visibility;globalCard.Visibility=region=="GLOBAL"&&a!=null&&!a.Archived?Visibility.Visible:Visibility.Collapsed;prepareButton.IsEnabled=a!=null&&a.Region=="CN"&&!a.Archived;UpdateBrowserChoices(a);UpdateCnExperiment(a);UpdateLoginStatus();UpdateGettingStarted();HidePassword();}
        void HidePassword(){revealTimer.Stop();secret.Text=Selected==null||string.IsNullOrEmpty(Selected.Password)?"未填写密码":"••••••••";if(showButton!=null)showButton.Content="显示密码 · 30 秒";}
        void Reveal(){var a=Require();if(string.IsNullOrEmpty(a.Password)){status.Text="这个账号没有填写密码，可只作为登录方式备忘。";return;}if(revealTimer.IsEnabled){HidePassword();return;}secret.Text=a.Password;showButton.Content="隐藏密码";revealTimer.Start();}
        void Copy(string field,string text){
            if(string.IsNullOrEmpty(text)){CopyFeedback(field+"未填写，请点“编辑账号”补充。",true);return;}
            try{if(copyToClipboard!=null)copyToClipboard(text);else clipboard.Copy(text);CopyFeedback(field+"已复制，可粘贴；30 秒后清除本工具的复制内容。",false);}
            catch(System.Runtime.InteropServices.ExternalException){CopyFeedback("剪贴板暂时被其他程序占用，请稍后再点一次复制。",true);}
            catch{CopyFeedback("复制未完成，请再试一次。原账号资料未改动。",true);}
        }
        Data Clone(){RequireVaultAccess();return data.Copy();}
        void Commit(Data updated,string id){RequireVaultAccess();store.Save(updated);data=updated;Refresh(id);UpdateStorageInfo();}
        void Add(){Stop();var edit=new Editor(this,Account.New("",region),data);if(edit.ShowDialog()!=true)return;var updated=Clone();updated.Accounts.Add(edit.Result);region=edit.Result.Region;search.Text="";favoriteOnly.IsChecked=false;archivedOnly.IsChecked=false;Commit(updated,edit.Result.Id);gettingStarted.IsExpanded=true;status.Text=region=="GLOBAL"?"账号已加密保存。首次使用请正常退出战网，点“首次登录 / 重新认证”，手动登录并勾选保持登录。":"账号已加密保存。让战网停在国服登录页，点“网页登录”完成首次认证。";}
        void Edit(){var a=Require();Stop();var edit=new Editor(this,a,data);if(edit.ShowDialog()!=true)return;var updated=Clone();updated.Accounts[updated.Accounts.FindIndex(x=>x.Id==a.Id)]=edit.Result;region=edit.Result.Region;search.Text="";Commit(updated,a.Id);status.Text="备忘已更新。";}
        void Favorite(){var a=Require();Stop();var updated=Clone();updated.Accounts.Single(x=>x.Id==a.Id).Favorite=!a.Favorite;Commit(updated,a.Id);}
        void Archive(){var a=Require();Stop();if(!a.Archived&&MessageBox.Show(this,"隐藏“"+a.Name+"”？\n账号资料不会删除，之后勾选“已隐藏账号”即可找回。","隐藏账号",MessageBoxButton.YesNo,MessageBoxImage.Question)!=MessageBoxResult.Yes)return;var updated=Clone();updated.Accounts.Single(x=>x.Id==a.Id).Archived=!a.Archived;Commit(updated,a.Id);status.Text=a.Archived?"账号已恢复到列表。":"账号已隐藏，勾选“已隐藏账号”即可找回。";}
        void UpdateBrowserChoices(Account a){updatingBrowser=true;try{string mode=a==null||string.IsNullOrEmpty(a.LoginBrowser)?"webview2":a.LoginBrowser;externalChoice.SelectedIndex=a!=null&&a.ExternalBrowser=="edge"?1:0;builtInChoice.IsChecked=mode=="webview2";otherChoice.IsChecked=mode!="webview2";routeHint.Text="本次登录使用："+Browser.Label(mode)+"。";browserSummary.Text="登录方式："+(mode=="webview2"?"内置窗口":Browser.Label(mode));}finally{updatingBrowser=false;}}
        string ExternalMode(){return externalChoice.SelectedIndex==1?"edge":"chrome";}
        void SetBrowserPreference(string mode,string external){var a=Require();if(a.Region!="CN"||a.Archived)throw new InvalidOperationException("请选择正常国服账号。");Stop();if(a.LoginBrowser==mode&&a.ExternalBrowser==external)return;var updated=Clone();var target=updated.Accounts.Single(x=>x.Id==a.Id);target.LoginBrowser=mode;target.ExternalBrowser=external;Commit(updated,a.Id);}
        void ChangeBrowser(){if(updatingBrowser||preview||busy||Selected==null)return;try{SetBrowserPreference(otherChoice.IsChecked==true?ExternalMode():"webview2",ExternalMode());status.Text="已记住此账号的网页登录方式。";}catch{UpdateBrowserChoices(Selected);status.Text="浏览器选择未能保存，原选择已保留。";}}
        void OpenBrowser(){var a=Require();string mode=ExternalMode();Browser.StartInfo(store.Home,a.Id,Browser.Home,mode);SetBrowserPreference(mode,mode);HidePassword();Browser.Open(store.Home,a.Id,Browser.Home,mode);status.Text="已打开“"+a.Name+"”的专用 "+Browser.Label(mode)+"，请以网页显示的账号为准。";Used(a.Id);}
        async void OpenEmbedded(){Account a;try{a=Require();if(a.Region!="CN"||a.Archived)throw new InvalidOperationException("请在国服列表选择正常账号。");}catch(Exception e){status.Text=e.Message;return;}try{SetBrowserPreference("webview2",ExternalMode());}catch{status.Text="登录方式未保存，原资料保留。";return;}Stop();HidePassword();SetBusy(true);status.Text="正在打开内置登录窗口…";try{await embedded.Open(a.Id,a.Name,Browser.Home);status.Text="已打开“"+a.Name+"”的内置窗口，请手动登录；账号网页资料独立保存。";Used(a.Id);}catch(Exception e){status.Text=e is InvalidOperationException?e.Message:"内置浏览器未能打开，请保留此提示。";ShowRecovery();}finally{SetBusy(false);}}
        void Used(string id){if(VaultDenied)return;var updated=Clone();updated.Accounts.Single(a=>a.Id==id).LastUsed=DateTime.UtcNow;try{Commit(updated,id);}catch{status.Text+=" 本次使用时间未保存，已发起的操作保持有效。";}}
        void SetBusy(bool value){if(value)ClearRecovery();busy=value;list.IsEnabled=!value;search.IsEnabled=!value;favoriteOnly.IsEnabled=!value;archivedOnly.IsEnabled=!value;skipClientCheck.IsEnabled=!value;cn.IsEnabled=!value;global.IsEnabled=!value;targets.IsEnabled=!value;builtInChoice.IsEnabled=!value;otherChoice.IsEnabled=!value;externalChoice.IsEnabled=!value;UpdateCnExperiment(Selected);UpdateVaultAccess();UpdateQuickCopy(Selected);}
    }
